findings.fix:
validation {
  condition     = can(regex("(@sha256:[a-f0-9]{64}|:[A-Za-z0-9_][A-Za-z0-9_.-]{0,127})$", var.container_image))
  error_message = "var.container_image must end in an explicit version tag or @sha256 digest"
}

validation {
  condition     = !can(regex("-compute@developer\\.gserviceaccount\\.com$", var.service_account))
  error_message = "var.service_account must be a dedicated service account, not the default Compute Engine service account"
}

lifecycle {
  precondition {
    condition     = var.max_executors_count >= var.executors_count
    error_message = "var.max_executors_count must be greater than or equal to var.executors_count"
  }
}
